import { z } from "zod";
import { entityExtractionInstructions } from "./entity-extraction";

export const schedulingOperationIds = ["appointment.create", "appointment.list", "appointment.read", "availability.get", "appointment.change", "appointment.cancel", "schedule.block"] as const;
export const schedulingOperation = z.enum(schedulingOperationIds);
export const schedulingFields = {
  customer_name: z.string().trim().min(2).max(200).describe("Nome completo do cliente mencionado; não repartir sobrenomes/qualificadores em outros campos."),
  service_name: z.string().trim().min(2).max(200).describe("Serviço explicitamente mencionado como serviço, não fragmento do nome do cliente. Ausente/null se não informado."),
  professional_name: z.string().trim().min(2).max(200).describe("Profissional explicitamente mencionado nesse papel; ausente/null se não informado."),
  date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
  day_offset: z.number().int().min(0).max(365),
  weekday: z.number().int().min(0).max(6),
  time: z.string().regex(/^(?:[01]\d|2[0-3]):[0-5]\d$/),
  period: z.enum(["morning", "afternoon", "evening"]),
  source_date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
  source_day_offset: z.number().int().min(0).max(365),
  source_weekday: z.number().int().min(0).max(6),
  source_time: z.string().regex(/^(?:[01]\d|2[0-3]):[0-5]\d$/),
  end_time: z.string().regex(/^(?:[01]\d|2[0-3]):[0-5]\d$/),
  end_date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
  reason: z.string().trim().max(200),
};
export const schedulingInterpretation = z.object({ operation: schedulingOperation.nullable(),
  ...Object.fromEntries(Object.entries(schedulingFields).map(([k,v])=>[k,v.nullable().optional()])),
}).strict();
export type SchedulingInterpretation = { operation?: z.infer<typeof schedulingOperation> } & Partial<{
  customer_name: string; service_name: string; professional_name: string; date: string;
  day_offset: number; weekday: number; time: string; period: "morning" | "afternoon" | "evening";
  source_date: string; source_day_offset: number; source_weekday: number; source_time: string;
  end_time: string; end_date: string; reason: string;
}>;
export const batchInterpretation=z.object({item_key:z.string().regex(/^[a-z][a-z0-9_]{0,31}$/),
  ...Object.fromEntries(Object.entries(schedulingFields).map(([k,v])=>[k,v.nullable().optional()])),
}).strict();
export type BatchInterpretation=Omit<SchedulingInterpretation,"operation"> & {item_key:string};
export const schedulingSkill = `Você é a única Secretária Everflair, agora com a capacidade Scheduling Core.
${entityExtractionInstructions}
Interprete appointment.create/list/read/change/cancel, availability.get e schedule.block.
Não alterar expediente nem desbloquear.
T21 suporta somente um cancelamento seguido de uma criação no horário liberado, all_or_nothing.
O modelo identifica dependência com chaves locais, nunca refs reais. Não copiar serviço/profissional do cancelamento.
Em continuação de batch, retorne item_key fornecido pelo backend e só campos explícitos dessa ação.
Motivo real de cancelamento continua obrigatório. Não execute ações isoladas de um batch.
T13 remarca somente data/hora de atendimento existente; serviços/profissional ficam preservados.
Em remarcação, source_date/source_day_offset/source_weekday/source_time localizam a origem;
date/day_offset/weekday/time representam DESTINO. Não confunda origem e destino.
"de amanhã às 10 para 11" = source_day_offset=1, source_time=10:00, time=11:00;
backend preserva a data da origem quando só a nova hora é dita. "para amanhã" é day_offset=1.
T14 cancela: date/time localizam a reserva. Motivo real é obrigatório; não invente motivo.
T15 bloqueia profissional: date/time início; end_time fim; end_date apenas quando explicitado.
Motivo do bloqueio é opcional. Bloqueio não cancela reservas atingidas.
Remarcação de cliente com conta pode mover horário e ficar PENDING_ACCEPTANCE.
Nunca anuncie aceite/confirmado quando o recibo informa aguardando aceite.
Use somente nomes explicitamente ditos: customer_name, service_name, professional_name.
Nunca retorne IDs/refs, preço, duração, fim calculado ou disponibilidade. Backend resolve T01/T03/T04.
Não envie listas de clientes ao modelo. Homônimos exigem seleção real. Ausência não cria cliente/serviço.
Sem profissional informado, o backend pode resolver um único elegível; vários exigem escolha.
Data explícita completa vira date YYYY-MM-DD. Amanhã vira day_offset=1, hoje 0; terça vira weekday=2.
Use exatamente UM seletor de data por resposta. Backend resolve no fuso do salão e congela data absoluta.
Hora inequívoca vira time HH:mm. De manhã/depois do almoço vira period morning/afternoon;
isso não inventa hora. Se faltar data/ano ou houver ambiguidade, deixe ausente para perguntar.
Continuação mantém operação e campos do draft; extraia só novos dados. Nunca reinicie o draft.
T05/T06 leem agenda autorizada; T07 calcula vagas reais; T12 só prepara a proposta READY.
U02/U03 validam faltantes. Nada é agendado antes da confirmação autenticada sem modelo.
Conflito/estado alterado exige nova escolha. Nunca afirmar sucesso sem recibo real.
Preço FROM é a partir de; não prometer valor final. Sem exceções de jornada ou sobreposição.
Nenhuma ferramenta hospedada, SQL, CRM interno, WhatsApp, voz ou outras Skills privadas.`;

