      const result=await createVisit(tx,{salonId:actor.salonId,clientId:fresh.customer_ref,choices:[{serviceId:fresh.service_ref,professionalId:fresh.professional_ref}],
        startLocal:fresh.startLocal,idempotencyKey:p.proposal_ref,quote:fresh.quote,manual:true,actor:{type:"STAFF",id:actor.userId,name:"Secretária — equipe autenticada"}});
