      return receiptSchema.parse({proposal_ref:p.proposal_ref,draft_ref:d.draft_ref,draft_revision:d.draft_revision,appointment_ref:result.appointmentIds[0],snapshot:fresh});
    },
  });
}

/** T13/T14/T15: existing U03 journal, revision and confirmation contract. */
export async function proposeSchedulingAction(tx:Tx,actor:ServiceActor,input:unknown){
