  await applySchedulingInterpretation(a,c.cancel,{operation:"appointment.cancel",...Object.fromEntries(Object.entries(cancel).filter(([k,v])=>keys.includes(k)&&v!=null))},message);
  await applyCommunicationInterpretation(a,c,send.communication??{},message);return c;
}
export async function sendCommunicationTurn(a:ServiceActor,c:CommunicationState,model:()=>Promise<Model>,message:string,assertLive:()=>unknown){
  c.proposal=undefined;const t=performance.now();
  if(c.cancel&&!c.cancel.draft?.action_snapshot){await sendSchedulingTurn(a,c.cancel,await model(),message,assertLive);await prepare(a,c);return;}
  const p=await runServicesTurn(await model(),message,{recipient_selected:Boolean(c.target),fields:c.fields,missing_fields:c.draft?.missing_fields},communicationRequirements(),"communication");
  c.metrics.interpretation=performance.now()-t;assertLive();await applyCommunicationInterpretation(a,c,p,message);
}

